    public Task<TdLib.TdApi.Objects.Emojis> GetAllStickerEmojisAsync(StickerType stickerType = default, string query = default, long chatId = default, bool returnOnlyMainEmoji = default)
    {

           using var activity =  StartCallActivity("GetAllStickerEmojisAsync", typeof(GetAllStickerEmojis).FullName ?? "GetAllStickerEmojisAsync");

           try
           {
             return client.GetAllStickerEmojisAsync(stickerType, query, chatId, returnOnlyMainEmoji);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
